dtsPropsFor.Button:
/** Visual style. `primary` is the single accent (oxblood); `destructive` is for dangerous actions ONLY; `link` renders inline. */
variant?: "primary" | "secondary" | "ghost" | "destructive" | "link";
/** Control height/padding. `icon` is a square icon-only button. */
size?: "sm" | "md" | "lg" | "icon";
/** Render as the single child element (Radix Slot), merging props onto it instead of a `<button>`. */
asChild?: boolean;
children?: React.ReactNode;
className?: string;
/** All native `<button>` attributes are also accepted (onClick, disabled, type, name, aria-*, …). */
disabled?: boolean;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
type?: "button" | "submit" | "reset";

dtsPropsFor.Badge:
/** Encryption-tier identity; selects the colour. `neutral` (default) is a plain grey pill. */
tier?: "server_readable" | "zero_access" | "end_to_end" | "neutral";
/** Badge content — a short label, optionally with a leading icon. */
children?: React.ReactNode;
className?: string;
title?: string;

dtsPropsFor.Card:
/** Card body. Compose with the compound parts exported from the same module: `CardHeader`, `CardTitle`, `CardDescription`, `CardContent`. */
children?: React.ReactNode;
className?: string;
/** All native `<div>` attributes are also accepted. */

dtsPropsFor.Dialog:
/** Controlled open state. Omit for uncontrolled (use `defaultOpen`). */
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/** When true (default), interaction outside the content is blocked. */
modal?: boolean;
/** Compose with `DialogTrigger`, `DialogContent`, `DialogHeader`, `DialogTitle`, `DialogDescription`, `DialogFooter`, `DialogClose` (all exported from the same module). */
children?: React.ReactNode;

dtsPropsFor.Progress:
/** Fill fraction, 0..1. Values > 1 clamp the bar to full and tint it crimson (over-quota). */
value: number;
/** CSS custom-property name for the fill colour (default "--color-brass-core", the accent). */
fillVar?: string;
className?: string;

dtsPropsFor.TierGlyph:
/** Which encryption crest to draw: shield (end-to-end), lock (zero-access), or eye (server-readable). */
glyph: "shield" | "lock" | "eye";
/** CSS custom-property name the glyph is lit in, e.g. "--color-tier-end-to-end". */
colorVar: string;
/** Square canvas size in pixels (default 34). */
size?: number;
/** Accessible label (defaults to "<glyph> tier mark"). */
label?: string;
